CREATE OR REPLACE FUNCTION private_mcpn.distribute_purchase_commission(p_buyer_id uuid, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_l1_id UUID; v_l2_id UUID; v_l3_id UUID;
    v_is_first_purchase BOOLEAN;
BEGIN
    IF p_amount < 10000 THEN RETURN; END IF;

    SELECT (COUNT(*) = 1) INTO v_is_first_purchase
    FROM public.sys_600
    WHERE user_id = p_buyer_id;

    IF v_is_first_purchase THEN
        -- Nível 1 (10%)
        SELECT patrocinador_id INTO v_l1_id FROM public.equipe_mcpn WHERE usuario_id = p_buyer_id;
        IF v_l1_id IS NOT NULL THEN
            UPDATE public.nucleo SET
                saldo_disponivel = saldo_disponivel + (p_amount * 0.10)
            WHERE id = v_l1_id;
            INSERT INTO public.extrato_mcpn (user_id, tipo, from_user_id, valor, nivel, detalhes)
            VALUES (v_l1_id, 'comissao_equipe', p_buyer_id, (p_amount * 0.10), 1,
                jsonb_build_object('descricao', 'Comissão Compra Direta', 'porcentagem_aplicada', 10))
            ON CONFLICT ON CONSTRAINT unique_comissao_evento DO NOTHING;

            -- Nível 2 (6%)
            SELECT patrocinador_id INTO v_l2_id FROM public.equipe_mcpn WHERE usuario_id = v_l1_id;
            IF v_l2_id IS NOT NULL THEN
                UPDATE public.nucleo SET
                    saldo_disponivel = saldo_disponivel + (p_amount * 0.06)
                WHERE id = v_l2_id;
                INSERT INTO public.extrato_mcpn (user_id, tipo, from_user_id, valor, nivel, detalhes)
                VALUES (v_l2_id, 'comissao_equipe', p_buyer_id, (p_amount * 0.06), 2,
                    jsonb_build_object('descricao', 'Comissão Compra Indireta L2', 'porcentagem_aplicada', 6))
                ON CONFLICT ON CONSTRAINT unique_comissao_evento DO NOTHING;

                -- Nível 3 (2%)
                SELECT patrocinador_id INTO v_l3_id FROM public.equipe_mcpn WHERE usuario_id = v_l2_id;
                IF v_l3_id IS NOT NULL THEN
                    UPDATE public.nucleo SET
                        saldo_disponivel = saldo_disponivel + (p_amount * 0.02)
                    WHERE id = v_l3_id;
                    INSERT INTO public.extrato_mcpn (user_id, tipo, from_user_id, valor, nivel, detalhes)
                    VALUES (v_l3_id, 'comissao_equipe', p_buyer_id, (p_amount * 0.02), 3,
                        jsonb_build_object('descricao', 'Comissão Compra Indireta L3', 'porcentagem_aplicada', 2))
                    ON CONFLICT ON CONSTRAINT unique_comissao_evento DO NOTHING;
                END IF;
            END IF;
        END IF;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.encrypt_data_mcpn(p_data text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_key TEXT := 'mcpn_secure_iban_key_2026_@ms';
BEGIN
    IF p_data IS NULL THEN RETURN NULL; END IF;
    RETURN extensions.pgp_sym_encrypt(p_data::text, v_key::text)::text;
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.encrypt_withdrawal_data_on_finish()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_encryption_key TEXT;
BEGIN
    -- Busca a chave de criptografia do cofre (vault)
    v_encryption_key := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'withdrawal_encryption_key');

    -- Dispara a criptografia se o status for alterado para 'aprovado', 'sucesso' ou 'falha'
    IF (NEW.status IN ('aprovado', 'sucesso', 'falha')) AND (OLD.status = 'pendente') THEN

        -- 1. Criptografar Banco de Destino
        IF NEW.banco_destino IS NOT NULL AND NEW.banco_destino NOT LIKE 'pgp%' THEN
            NEW.banco_destino := encode(extensions.pgp_sym_encrypt(NEW.banco_destino, v_encryption_key), 'base64');
        END IF;

        -- 2. Criptografar IBAN Snapshot
        IF NEW.iban_snapshot IS NOT NULL AND NEW.iban_snapshot NOT LIKE 'pgp%' THEN
            NEW.iban_snapshot := encode(extensions.pgp_sym_encrypt(NEW.iban_snapshot, v_encryption_key), 'base64');
        END IF;

        -- 3. Criptografar Nome do Usuário (Dono da conta Microsoft)
        IF NEW.nome_usuario IS NOT NULL AND NEW.nome_usuario NOT LIKE 'pgp%' THEN
            NEW.nome_usuario := encode(extensions.pgp_sym_encrypt(NEW.nome_usuario, v_encryption_key), 'base64');
        END IF;

        -- 4. Criptografar Nome do Beneficiário (Titular do Banco)
        IF NEW.nome_beneficiario IS NOT NULL AND NEW.nome_beneficiario NOT LIKE 'pgp%' THEN
            NEW.nome_beneficiario := encode(extensions.pgp_sym_encrypt(NEW.nome_beneficiario, v_encryption_key), 'base64');
        END IF;

    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.generate_invite_code_4char()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private_mcpn', 'extensions', 'pg_temp'
AS $function$
DECLARE
  upper_chars CONSTANT text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  lower_chars CONSTANT text := 'abcdefghijklmnopqrstuvwxyz';
  digits CONSTANT text := '0123456789';
  v_u char(1);
  v_l1 char(1);
  v_l2 char(1);
  v_d char(1);
  v_code text;
  v_exists boolean;
BEGIN
  LOOP
    v_u := substr(upper_chars, floor(random() * 26 + 1)::int, 1);
    v_l1 := substr(lower_chars, floor(random() * 26 + 1)::int, 1);
    v_l2 := substr(lower_chars, floor(random() * 26 + 1)::int, 1);
    v_d := substr(digits, floor(random() * 10 + 1)::int, 1);

    SELECT string_agg(x, '') INTO v_code
    FROM (
      SELECT unnest(ARRAY[v_u, v_l1, v_l2, v_d]) AS x
      ORDER BY random()
    ) sub;

    SELECT EXISTS (
      SELECT 1 FROM public.nucleo WHERE codigo_meu_refferal = v_code
    ) INTO v_exists;

    EXIT WHEN NOT v_exists;
  END LOOP;

  RETURN v_code;
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.link_bank_account_mcpn(p_bank_name text, p_holder_name text, p_iban text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_user_id         UUID := auth.uid();
    v_encrypted_iban  TEXT;
    v_encrypted_holder TEXT;
    v_json            jsonb;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Sessão expirada.');
    END IF;

    v_encrypted_iban   := private_mcpn.encrypt_data_mcpn(p_iban);
    v_encrypted_holder := private_mcpn.encrypt_data_mcpn(p_holder_name);

    v_json := jsonb_build_object(
        'nome_banco',    p_bank_name,
        'nome_completo', v_encrypted_holder,
        'iban',          v_encrypted_iban
    );

    -- Agora grava em nucleo em vez de sys_t111
    UPDATE public.nucleo
    SET dados_bancarios = v_json
    WHERE id = v_user_id;

    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Utilizador não encontrado.');
    END IF;

    RETURN json_build_object('success', true, 'message', 'Conta vinculada com sucesso.');
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.pestgay(p_code text DEFAULT NULL::text, p_action text DEFAULT 'redeem'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn', 'pg_temp'
AS $function$
DECLARE
    v_user_id        UUID := auth.uid();
    v_clean_code     TEXT;
    v_coupon_id      UUID;
    v_valor          NUMERIC;
    v_usos_restantes INTEGER;
    v_receipt_hash   TEXT;
    v_history        JSONB;
    v_resgates       JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Sessão expirada ou não autenticado.');
    END IF;

    -- Ação: Histórico de cupões resgatados pelo utilizador
    IF lower(trim(COALESCE(p_action, 'redeem'))) IN ('history', 'list', 'my_coupons', 'consultar') THEN
        SELECT COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'id',              c.id,
                    'created_at',      r->>'resgatado_em',
                    'valor',           c.valor,
                    'codigo_mascarado', concat(left(c.codigo_cupom, 2), '***', right(c.codigo_cupom, 2))
                ) ORDER BY (r->>'resgatado_em') DESC
            ),
            '[]'::jsonb
        ) INTO v_history
        FROM public.cupons c,
             jsonb_array_elements(c.resgates) AS r
        WHERE (r->>'user_id')::uuid = v_user_id;

        RETURN jsonb_build_object('success', true, 'action', 'history', 'coupons', v_history);
    END IF;

    -- Ação padrão: Resgate
    v_clean_code := upper(trim(regexp_replace(COALESCE(p_code, ''), '[^A-Za-z0-9]', '', 'g')));
    IF length(v_clean_code) < 5 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Código de cupom inválido.');
    END IF;

    -- Busca atómica com lock
    SELECT id, valor, usos_restantes, resgates
    INTO v_coupon_id, v_valor, v_usos_restantes, v_resgates
    FROM public.cupons
    WHERE upper(trim(codigo_cupom)) = v_clean_code AND ativo = true
    FOR UPDATE;

    IF v_coupon_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Cupom inválido ou inexistente.');
    END IF;

    IF v_usos_restantes IS NOT NULL AND v_usos_restantes <= 0 THEN
        UPDATE public.cupons SET ativo = false WHERE id = v_coupon_id;
        RETURN jsonb_build_object('success', false, 'message', 'Este cupom já se encontra esgotado.');
    END IF;

    -- Verificar se este utilizador já resgatou (consultar jsonb)
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_resgates) AS r
        WHERE (r->>'user_id')::uuid = v_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Você já resgatou este cupom anteriormente.');
    END IF;

    -- Registar resgate no jsonb resgates
    UPDATE public.cupons
    SET resgates       = resgates || jsonb_build_object(
                            'user_id', v_user_id,
                            'resgatado_em', now()
                         ),
        usos_restantes = CASE
                            WHEN usos_restantes IS NOT NULL
                            THEN GREATEST(0, usos_restantes - 1)
                            ELSE NULL
                         END,
        ativo          = CASE
                            WHEN usos_restantes IS NOT NULL AND (usos_restantes - 1) <= 0
                            THEN false
                            ELSE ativo
                         END
    WHERE id = v_coupon_id;

    -- Creditar saldo em nucleo
    UPDATE public.nucleo
    SET saldo_disponivel = COALESCE(saldo_disponivel, 0) + v_valor,
        updated_at       = now()
    WHERE id = v_user_id;

    -- Hash do recibo
    v_receipt_hash := encode(
        digest(v_user_id::text || ':' || v_coupon_id::text || ':' || extract(epoch from now())::text, 'sha256'),
        'hex'
    );

    -- Notificação in-app
    BEGIN
        INSERT INTO public.sacola (user_id, title, body, payload, status)
        VALUES (
            v_user_id,
            'Cupom Ativado! 🎉',
            'Recebeste +' || trim(to_char(v_valor, 'FM999,999,990.00')) || ' Kz na tua carteira.',
            jsonb_build_object('url', '/carteira', 'receipt', v_receipt_hash, 'tipo', 'cupom'),
            'pending'
        );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Resgatado! + ' || trim(to_char(v_valor, 'FM999,999,990.00')) || ' Kz.',
        'amount',  v_valor,
        'receipt', v_receipt_hash
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN jsonb_build_object('success', false, 'message', 'Você já resgatou este cupom anteriormente.');
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'message', 'Falha ao processar cupom: ' || SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.process_registration_bonus()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_invites_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_invites_count FROM public.equipe_mcpn WHERE patrocinador_id = NEW.patrocinador_id;

    IF v_invites_count <= 10 THEN
        BEGIN
            INSERT INTO public.bonus_equipe_mcpn (user_id, from_user_id, valor, nivel, detalhes, created_at)
            VALUES (NEW.patrocinador_id, NEW.usuario_id, 50.00, 1, jsonb_build_object('tipo', 'Bônus de Cadastro Direto'), now());

            UPDATE public.nucleo 
            SET saldo_disponivel = saldo_disponivel + 50.00,
                updated_at = now()
            WHERE id = NEW.patrocinador_id;
        EXCEPTION WHEN unique_violation THEN
            NULL;
        END;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.process_withdrawal_request(p_amount numeric, p_bank_id uuid DEFAULT NULL::uuid, p_password text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_balance NUMERIC;
    v_bank_name TEXT; 
    v_iban TEXT; 
    v_nome_beneficiario TEXT;
    v_user_phone TEXT;
BEGIN
    IF v_user_id IS NULL THEN 
        RETURN json_build_object('success', false, 'message', 'Sessão expirada.'); 
    END IF;

    -- Limite de 1 retirada por dia
    IF EXISTS (
        SELECT 1 FROM public.retiradas_mcpn 
        WHERE user_id = v_user_id 
        AND DATE(created_at AT TIME ZONE 'Africa/Luanda') = DATE(now() AT TIME ZONE 'Africa/Luanda')
    ) THEN
        RETURN json_build_object('success', false, 'message', 'Limite diário (1) retirada atingido.');
    END IF;

    -- Não permitir nova retirada se houver pendente
    IF EXISTS (
        SELECT 1 FROM public.retiradas_mcpn 
        WHERE user_id = v_user_id 
        AND status = 'pendente'
    ) THEN
        RETURN json_build_object('success', false, 'message', 'Você já possui uma retirada pendente. Aguarde a aprovação.');
    END IF;

    -- Saldo suficiente
    SELECT saldo_disponivel, telefone INTO v_balance, v_user_phone FROM public.nucleo WHERE id = v_user_id;
    IF v_balance IS NULL OR v_balance < p_amount THEN 
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente.'); 
    END IF;

    -- Dados bancários de sys_t111
    SELECT 
        (dados_bancarios->>'nome_banco')::text, 
        COALESCE(private_mcpn.decrypt_data_mcpn(dados_bancarios->>'iban'), 'Erro IBAN'),
        COALESCE(private_mcpn.decrypt_data_mcpn(dados_bancarios->>'nome_completo'), 'Erro Titular')
    INTO v_bank_name, v_iban, v_nome_beneficiario
    FROM public.sys_t111 
    WHERE user_id = v_user_id 
    LIMIT 1;

    IF v_bank_name IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Nenhuma conta bancária vinculada. Vincule uma conta antes de sacar.');
    END IF;

    -- Deduz do saldo
    UPDATE public.nucleo 
    SET saldo_disponivel = saldo_disponivel - p_amount, 
        total_retirado = total_retirado + p_amount, 
        updated_at = now() 
    WHERE id = v_user_id;

    -- Insere retirada
    INSERT INTO public.retiradas_mcpn (
        user_id, 
        valor_bruto, 
        dados_bancarios_snapshot,
        status, 
        created_at
    ) VALUES (
        v_user_id, 
        p_amount, 
        jsonb_build_object(
            'banco', v_bank_name,
            'iban', v_iban,
            'nome_beneficiario', COALESCE(v_nome_beneficiario, 'Indefinido'),
