CREATE OR REPLACE FUNCTION private_mcpn.push_on_chat_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_sub RECORD;
  v_nome TEXT;
  v_telefone TEXT;
  v_sender TEXT;
  v_conteudo TEXT;
  v_tipo_midia TEXT;
  v_body TEXT;
BEGIN
  SELECT NULLIF(trim(nome_exibicao), ''), NULLIF(trim(telefone), '')
  INTO v_nome, v_telefone
  FROM public.nucleo
  WHERE id = NEW.uid_emissor;

  IF v_nome IS NOT NULL AND v_telefone IS NOT NULL THEN
    v_sender := v_nome || ' (' || v_telefone || ')';
  ELSIF v_nome IS NOT NULL THEN
    v_sender := v_nome;
  ELSIF v_telefone IS NOT NULL THEN
    v_sender := v_telefone;
  ELSE
    v_sender := 'Utilizador';
  END IF;

  v_tipo_midia := LOWER(COALESCE(NEW.detalhes->>'tipo_midia', ''));
  v_conteudo := NULLIF(trim(NEW.mensagem), '');

  IF v_tipo_midia IN ('imagem', 'foto') THEN
    v_conteudo := COALESCE('[Foto] ' || v_conteudo, '[Foto]');
  ELSIF v_tipo_midia IN ('audio', 'voz') OR NEW.detalhes->>'tipo_audio' IS NOT NULL THEN
    v_conteudo := '[Mensagem de voz]';
  ELSIF v_tipo_midia = 'video' THEN
    v_conteudo := '[Video]';
  ELSIF v_tipo_midia IN ('arquivo', 'documento', 'pdf') OR NEW.detalhes->>'storagePath' IS NOT NULL THEN
    v_conteudo := '[Documento]';
  ELSIF v_conteudo IS NULL THEN
    v_conteudo := 'Enviou uma nova mensagem';
  END IF;

  IF length(v_conteudo) > 160 THEN
    v_conteudo := left(v_conteudo, 157) || '...';
  END IF;

  v_body := v_sender || ': ' || v_conteudo;

  FOR v_sub IN
    SELECT id AS user_id FROM public.nucleo
    WHERE id != NEW.uid_emissor 
      AND webpush_subscription IS NOT NULL 
      AND jsonb_array_length(webpush_subscription) > 0
    LIMIT 100
  LOOP
    INSERT INTO public.sacola (user_id, title, body, payload, status)
    VALUES (
      v_sub.user_id,
      'Busne Messaging',
      v_body,
      jsonb_build_object('url', '/chat-comunidade'),
      'pending'
    );
  END LOOP;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.secure_registration_mcpn(p_phone text, p_invite_code text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_patrocinador_id varchar;
BEGIN
    -- 1. Validar se o telefone já existe
    IF EXISTS (SELECT 1 FROM public.perfis_mcpn WHERE telefone = p_phone) THEN
        PERFORM public.log_ip_audit_mcpn(NULL, 'registration_check_failed', false, jsonb_build_object('phone', p_phone, 'reason', 'already_exists'));
        RETURN json_build_object('success', false, 'message', 'Este número de telefone já está registrado no sistema Microsoft Cloud.');
    END IF;

    -- 2. Validar o Código de Convite
    SELECT id INTO v_patrocinador_id 
    FROM public.perfis_mcpn 
    WHERE codigo_meu_refferal = p_invite_code 
    LIMIT 1;

    IF v_patrocinador_id IS NULL THEN
        PERFORM public.log_ip_audit_mcpn(NULL, 'registration_check_failed', false, jsonb_build_object('phone', p_phone, 'reason', 'invalid_invite_code', 'code', p_invite_code));
        RETURN json_build_object('success', false, 'message', 'Código de convite inválido ou expirado.');
    END IF;

    -- Log de sucesso na validação
    PERFORM public.log_ip_audit_mcpn(NULL, 'registration_check_success', true, jsonb_build_object('phone', p_phone, 'invite_code', p_invite_code));

    RETURN json_build_object(
        'success', true, 
        'message', 'Dados validados. Você pode prosseguir com a criação da conta.',
        'patrocinador_id', v_patrocinador_id
    );
END;
$function$

