CREATE OR REPLACE FUNCTION private_mcpn.submit_social_proof_mcpn(p_valor numeric, p_comentario text, p_imagem_url text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_ultima_postagem TIMESTAMPTZ;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Sessão expirada. Autentique-se novamente.');
    END IF;

    SELECT created_at INTO v_ultima_postagem 
    FROM public.social_proofs_mcpn 
    WHERE user_id = v_user_id 
    ORDER BY created_at DESC LIMIT 1;

    IF v_ultima_postagem IS NOT NULL AND (now() - v_ultima_postagem) < interval '24 hours' THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Você só pode publicar uma prova social a cada 24 horas. Próxima publicação disponível em ' || (v_ultima_postagem + interval '24 hours')::text
        );
    END IF;

    IF p_valor IS NULL OR p_valor < 1000 THEN
        RETURN json_build_object('success', false, 'message', 'O valor mínimo para prova social é 1.000 Kz.');
    END IF;

    p_comentario := trim(p_comentario);
    IF length(p_comentario) < 5 OR length(p_comentario) > 500 THEN
        RETURN json_build_object('success', false, 'message', 'O comentário deve ter entre 5 e 500 caracteres.');
    END IF;

    IF p_imagem_url IS NULL OR trim(p_imagem_url) = '' THEN
        RETURN json_build_object('success', false, 'message', 'É necessário anexar uma imagem do comprovativo.');
    END IF;

    INSERT INTO public.social_proofs_mcpn (
        user_id, 
        valor, 
        conteudo,
        status,
        created_at
    )
    VALUES (
        v_user_id, 
        p_valor, 
        jsonb_build_object('comentario', p_comentario, 'imagem_url', p_imagem_url),
        'aprovado',
        now()
    );

    RETURN json_build_object(
        'success', true, 
        'message', 'Prova social publicada com sucesso! Volte amanhã para publicar novamente.'
    );
END;
$function$

CREATE OR REPLACE FUNCTION private_mcpn.toggle_reaction_mcpn(p_message_id bigint, p_emoji text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_old_data jsonb;
  v_reactions jsonb;
  v_new_reactions jsonb := '{}'::jsonb;
  v_key text;
  v_user_list jsonb;
  v_already_reacted_with_this_emoji boolean := false;
BEGIN
  SELECT COALESCE(NULLIF(reacoes_emojis, '')::jsonb, '{}'::jsonb) 
  INTO v_old_data 
  FROM public.chat_gruop 
  WHERE id = p_message_id;

  v_reactions := COALESCE(v_old_data->'reactions', '{}'::jsonb);

  FOR v_key IN SELECT jsonb_object_keys(v_reactions) LOOP
    v_user_list := v_reactions->v_key;
    IF v_key = p_emoji AND v_user_list @> jsonb_build_array(p_user_id) THEN
      v_already_reacted_with_this_emoji := true;
    END IF;
    v_user_list := v_user_list - p_user_id::text;
    IF jsonb_array_length(v_user_list) > 0 THEN
      v_new_reactions := v_new_reactions || jsonb_build_object(v_key, v_user_list);
    END IF;
  END LOOP;

  IF NOT v_already_reacted_with_this_emoji THEN
    v_user_list := COALESCE(v_new_reactions->p_emoji, '[]'::jsonb);
    v_user_list := v_user_list || jsonb_build_array(p_user_id);
    v_new_reactions := v_new_reactions || jsonb_build_object(p_emoji, v_user_list);
  END IF;

  UPDATE public.chat_gruop 
  SET reacoes_emojis = (v_old_data || jsonb_build_object('reactions', v_new_reactions))::text 
  WHERE id = p_message_id;

  RETURN v_old_data || jsonb_build_object('reactions', v_new_reactions);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_coupon_mcpn(p_codigo text, p_valor numeric, p_usos_max integer DEFAULT 9999, p_admin_secret text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'private_mcpn'
AS $function$
DECLARE
    v_codigo_clean text;
    v_novo_id uuid;
BEGIN
    -- Verificar segredo de admin (defina no seu painel)
    IF p_admin_secret IS DISTINCT FROM current_setting('app.admin_secret', true) THEN
        RAISE EXCEPTION 'Não autorizado.';
    END IF;

    -- Sanitizar código
    v_codigo_clean := upper(trim(regexp_replace(COALESCE(p_codigo, ''), '[^A-Za-z0-9]', '', 'g')));
    IF length(v_codigo_clean) < 4 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Código muito curto. Mínimo 4 caracteres.');
    END IF;

    -- Verificar se já existe
    IF EXISTS (SELECT 1 FROM public.cupons WHERE upper(trim(codigo_cupom)) = v_codigo_clean) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Este código já existe.');
    END IF;

    -- Inserir novo cupão
    INSERT INTO public.cupons (codigo_cupom, valor, ativo, usos_restantes, resgates)
    VALUES (v_codigo_clean, p_valor, true, p_usos_max, '[]'::jsonb)
    RETURNING id INTO v_novo_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Cupão criado com sucesso!',
        'id', v_novo_id,
        'codigo', v_codigo_clean,
        'valor', p_valor,
        'usos_max', p_usos_max
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

